/**
 * chatAdapter — risk #3: bridges our `parts` discriminated union (chatStore)
 * onto Heimdall's `<ChatMessage>` shape (single `body` + optional `toolBlock`
 * + optional `thinkingBlock`).
 *
 * Our wire model (see `types/chat.ts`) lets one assistant message carry an
 * ordered mix of `text`, `thinking`, `tool_invocation`, `usage`, and `error`
 * parts. Heimdall's `<ChatMessage>` renders exactly one body and at most one
 * tool/thinking block. So we flatten each store message into one-or-more
 * Heimdall message view-models ("rows"), preserving part order:
 *
 *   - consecutive `text` parts coalesce into a markdown body;
 *   - each `thinking` part becomes a row carrying a `thinkingBlock`;
 *   - each `tool_invocation` part becomes a row carrying a `toolBlock`
 *     (status executing -> running, completed -> success, failed -> error);
 *   - `error` parts become an inline error row (rendered red by ChatPanel);
 *   - `usage` parts become a subtle meta row.
 *
 * `body` is returned as a plain string here; ChatPanel renders it through
 * Heimdall's `<ChatMarkdownContent>` (the adapter stays render-prop free so it
 * is trivially unit-testable). The adapter is pure — re-run it on every
 * chatStore change.
 */

import type {
  ChatMessage,
  ChatContent,
  TextContent,
  ThinkingContent,
  ToolInvocationContent,
  UsageContent,
  ErrorContent,
} from '../types/chat';
import type { ToolBlockData, ThinkingBlockData } from '@tinkermonkey/heimdall-ui';

export type HeimdallRole = 'user' | 'bot';

/** Kind of body a row carries, so ChatPanel can pick the right renderer. */
export type RowBodyKind = 'markdown' | 'error' | 'usage';

/**
 * A flattened, render-ready row mapping onto a single Heimdall `<ChatMessage>`.
 * `id` is stable per (message, segment) so React keys stay consistent across
 * streaming updates.
 */
export interface HeimdallChatRow {
  id: string;
  role: HeimdallRole;
  senderName: string;
  timestamp: string;
  /** Concatenated markdown (or the error/usage text); '' when only a block. */
  body: string;
  bodyKind: RowBodyKind;
  /** True while the source message is still streaming (markdown cursor). */
  isStreaming: boolean;
  toolBlock?: ToolBlockData;
  thinkingBlock?: ThinkingBlockData;
}

/** 'user' stays user; 'assistant' and 'system' both render as the bot. */
function toHeimdallRole(role: ChatMessage['role']): HeimdallRole {
  return role === 'user' ? 'user' : 'bot';
}

function senderFor(role: ChatMessage['role']): string {
  return role === 'user' ? 'You' : 'DrBot';
}

/** HH:MM local time from an ISO timestamp (falls back to the raw string). */
function formatTime(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

/** executing -> running, completed -> success, failed -> error. */
function toToolStatus(
  status: ToolInvocationContent['status'],
): ToolBlockData['status'] {
  switch (status.state) {
    case 'executing':
      return 'running';
    case 'completed':
      return 'success';
    case 'failed':
      return 'error';
    default:
      return 'running';
  }
}

/** Render an arbitrary value compactly for a tool-block output row. */
function valueToString(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

/**
 * Build the tool-block output rows: the tool input keys, then a result/error
 * row reflecting terminal status.
 */
function toolOutput(part: ToolInvocationContent): ToolBlockData['output'] {
  const rows: NonNullable<ToolBlockData['output']> = [];

  const input = part.toolInput ?? {};
  for (const [key, value] of Object.entries(input)) {
    rows.push({ key, value: valueToString(value) });
  }

  if (part.status.state === 'completed' && part.status.result !== undefined) {
    rows.push({ key: 'result', value: valueToString(part.status.result) });
  } else if (part.status.state === 'failed') {
    rows.push({ key: 'error', value: part.status.error });
  }

export class EmbeddedDataLoader {
  /**
   * Generic fetch helper that combines common pattern: fetch -> ensureOk -> json -> log
   *
   * IMPORTANT: This method uses a type assertion (as T) without runtime validation.
   * The response is NOT validated to match the expected type T. Unlike ChangesetChange
   * which uses runtime validation (validateChangesetChanges), this method assumes the
   * server response matches the declared type. Use only for endpoints with stable,
   * well-documented response schemas. For new endpoints, consider adding runtime validation.
   *
   * @param url - URL to fetch
   * @param context - Context string for error logging
   * @param options - Additional fetch options
   * @returns Parsed JSON response (type assertion only, not validated)
   */
  private async fetchJson<T>(
    url: string,
    context: string,
    options?: RequestInit
  ): Promise<T> {
    const response = await fetch(url, {
      headers: getAuthHeaders(),
      credentials: 'include',
      ...options
    });

    await ensureOk(response, context);

    const data = await response.json();
    return data as T;
  }

  /**
   * Check server health
   */
  async healthCheck(): Promise<{ status: string; version: string }> {
    return this.fetchJson<{ status: string; version: string }>(
      '/health',
      'health check'
    );
  }

  /**
   * Load the specification (JSON Schema format)
   * Normalizes server response to camelCase property names
   */
  async loadSpec(): Promise<SpecDataResponse> {
    const response = await fetch(`${API_BASE}/spec`, {
      headers: getAuthHeaders(),
      credentials: 'include'
    });

    await ensureOk(response, 'load spec');

    // Type the raw response to narrow the untyped JSON
    const data = (await response.json()) as Record<string, unknown> & {
      version?: string;
      type?: string;
      schemas?: Record<string, unknown>;
      schemaCount?: number;
      schema_count?: number;
      relationshipCatalog?: RelationshipCatalog;
      relationship_catalog?: RelationshipCatalog;
    };

    // Normalize snake_case from server to camelCase for TypeScript
    const schemaCount = data.schemaCount ?? data.schema_count ?? (data.schemas ? Object.keys(data.schemas).length : 0);
    const relationshipCatalog: RelationshipCatalog | undefined = data.relationshipCatalog || data.relationship_catalog;

    const result: SpecDataResponse = {
      version: data.version ?? '',
      type: data.type ?? '',
      schemas: (data.schemas ?? {}) as Record<string, SchemaDefinition>,
      schemaCount,
      relationshipCatalog
    };

    if (typeof data.description === 'string') {
      result.description = data.description;
    }
    if (typeof data.source === 'string') {
      result.source = data.source;
    }
    if (data.manifest && typeof data.manifest === 'object') {
      result.manifest = data.manifest as SchemaManifest;
    }

    return result;
  }

  /**
   * Load a specific layer by name
   */
  async loadLayer(layerName: string): Promise<{ name: string; elements: unknown[]; elementCount: number }> {
    const data = await this.fetchJson<{ name: string; elements: unknown[]; elementCount: number }>(
      `${API_BASE}/layers/${encodeURIComponent(layerName)}`,
      `load layer ${layerName}`
    );
    return data;
  }

  /**
   * Load a specific element by ID
   * Generic type parameter allows callers to specify expected return type
   */
  async loadElement<T = unknown>(elementId: string): Promise<T> {
    const data = await this.fetchJson<T>(
      `${API_BASE}/elements/${encodeURIComponent(elementId)}`,
      `load element ${elementId}`
    );
    return data;
  }

  /**
   * Load the current model (YAML instance format)
   */
  async loadModel(): Promise<MetaModel> {
    const data = await this.fetchJson<Record<string, unknown> & {
      version?: string;
      metadata?: Record<string, unknown>;

export interface ChangesetDetails {
  metadata: ChangesetMetadata;
  changes: {
    version: string;
