}

function RowBody({ row }: { row: HeimdallChatRow }) {
  if (row.bodyKind === 'error') {
    return (
      <span
        style={{ color: '#F43F5E', fontSize: 12.5, lineHeight: 1.5 }}
        data-testid="chat-error-line"
      >
        {row.body}
      </span>
    );
  }
  if (row.bodyKind === 'usage') {
    return (
      <span
        style={{
          fontFamily: "'JetBrains Mono', monospace",
          fontSize: 10.5,
          color: 'rgb(var(--canvas-fg-3))',
        }}
      >
        {row.body}
      </span>
    );
  }
  return <ChatMarkdownContent content={row.body} isStreaming={row.isStreaming} />;
}

send(message: WebSocketSendMessage): boolean {
  if (this.ws && this.ws.readyState === WS_OPEN) {
    try {
      this.ws.send(JSON.stringify(message));
      return true;
    } catch (error) {
      logError(
        ERROR_IDS.WS_SEND_FAILED,
        'Failed to send WebSocket message',
        { error: error instanceof Error ? error.message : String(error), message }
      );
      return false;
    }
  } else {
    logError(
      ERROR_IDS.WS_NOT_CONNECTED,
      'Cannot send message, WebSocket not connected',
      { connectionState: this.ws?.readyState, message }
    );
    return false;
  }
}

/**
 * specGraph — pure transforms of the `/api/spec` payload into per-layer Heimdall
 * Schema (meta-model) view models (node-types + edges) and inspector data.
 *
 * `/api/spec` is a `schema-collection`: `schemas['<slug>.json']` holds each
 * layer schema with `layer`, `nodeSchemas` (keyed by short type name, e.g.
 * `objectschema`), and `relationshipSchemas` (keyed by a fully-qualified rel id).
 *
 * Node-type id is the `spec_node_id` = `<slug>.<shortname>`. Relationships carry
 * `source_spec_node_id` / `destination_spec_node_id` (already in that dotted
 * form), source/destination layer, predicate, and cardinality. Intra-layer
 * relationships (`source_layer === destination_layer === slug`) become graph
 * edges; cross-layer relationships surface only in the inspector (so they can
 * color + navigate across layers).
 *
 * All functions are pure: they accept the raw `/api/spec` payload and a layer
 * slug, returning deterministic results. Node positions are left unset so
 * `GraphCanvas`'s `layout="force"` engine places them, same as `modelGraph`.
 */

import type {
  GraphNodeData,
  GraphEdgeData as GraphEdge,
  RelationshipLink,
  GraphNodeMetadata,
} from '@tinkermonkey/heimdall-ui';

// ─── Raw /api/spec shapes (only the fields this module reads) ─────────────────

export interface SpecLayerBlock {
  id?: string;
  number?: number;
  name?: string;
  description?: string;
  node_types?: string[];
  inspired_by?: { standard?: string; version?: string; url?: string };
}

export interface SpecNodeSchema {
  title?: string;
  description?: string;
  required?: string[];
  /** `[{ $ref: 'urn:dr:spec:base:spec-node' }]` — the base schema this node type extends. */
  allOf?: Array<{ $ref?: string }>;
  /** `urn:dr:spec:node:<layer>.<type>` — this node type's own schema id. */
  $id?: string;
  properties?: {
    spec_node_id?: { const?: string };
    attributes?: {
      required?: string[];
      properties?: Record<string, { type?: string; [key: string]: unknown }>;
    };
    [key: string]: unknown;
  };
  [key: string]: unknown;
}

export interface SpecRelationshipSchema {
  id: string;
  source_spec_node_id: string;
  source_layer: string;
  destination_spec_node_id: string;
  destination_layer: string;
  predicate: string;
  cardinality?: string;
  strength?: string;
  required?: boolean;
}

export interface SpecLayerSchema {
  specVersion?: string;
  layer?: SpecLayerBlock;
  nodeSchemas?: Record<string, SpecNodeSchema>;
  relationshipSchemas?: Record<string, SpecRelationshipSchema>;
}

export interface SpecPayload {
  version?: string;
  type?: string;
  schemas?: Record<string, unknown>;
  [key: string]: unknown;
}

// ─── Schema lookup ────────────────────────────────────────────────────────────

/** The layer schema for a slug, or undefined when the layer/file is missing. */
export function schemaForLayer(
  spec: SpecPayload | undefined,
  slug: string,
): SpecLayerSchema | undefined {
  const entry = spec?.schemas?.[`${slug}.json`];
  return entry as SpecLayerSchema | undefined;
}

/**
 * The short type name from a `spec_node_id` (`data-model.objectschema` ->
 * `objectschema`) given the owning layer slug. Falls back to the segment after
 * the last dot when the prefix doesn't match (defensive only).
 */
export function shortName(slug: string, specNodeId: string): string {
  const prefix = `${slug}.`;
  if (specNodeId.startsWith(prefix)) return specNodeId.slice(prefix.length);
  const dot = specNodeId.lastIndexOf('.');
  return dot >= 0 ? specNodeId.slice(dot + 1) : specNodeId;
}

/**
 * Resolve a `spec_node_id` to its human title by looking up the destination
 * layer's `nodeSchemas`. Falls back to the short type name when the title (or
 * the destination layer schema) is unavailable — so cross-layer targets still
 * read sensibly.
 */
export function titleForSpecNode(
  spec: SpecPayload | undefined,
  layer: string,
  specNodeId: string,
): string {
  const short = shortName(layer, specNodeId);
  const schema = schemaForLayer(spec, layer);
  return schema?.nodeSchemas?.[short]?.title ?? short;

export class ChatService {
  private currentConversationId: string | null = null;
  private currentRequestId: string | null = null;
  /** Tools reported without a status. The server sends one notification per
   *  call and never reports completion, so these are marked completed when
   *  the reply moves on (next tool or text) or ends. */
  private statuslessToolIds = new Set<string>();
  private toolIdCounter = 0;

  constructor() {
    this.setupNotificationHandlers();
  }

  /**
   * Setup handlers for server notifications (called in constructor)
   *
   * Side Effects:
   * - Registers 5 notification handlers with `jsonRpcHandler` via `onNotification()`:
   *   1. 'chat.response.chunk' → calls `handleResponseChunk()`
   *   2. 'chat.tool.invoke' → calls `handleToolInvoke()`
   *   3. 'chat.thinking' → calls `handleThinking()`
   *   4. 'chat.usage' → calls `handleUsage()`
   *   5. 'chat.error' → calls `handleError()`
   *
   * These handlers are called asynchronously by the JSON-RPC handler when the server
   * sends notifications during message streaming. Each handler updates the chat store
   * to track the streaming response in real-time.
   *
   * Important: These are notification handlers (fire-and-forget), not request/response pairs.
   * They are triggered independently of the main `sendMessage()` promise resolution.
   */
  private setupNotificationHandlers(): void {
    // Handle text response chunks
    jsonRpcHandler.onNotification('chat.response.chunk', (params: any) => {
      this.handleResponseChunk(params);
    });

    // Handle tool invocations
    jsonRpcHandler.onNotification('chat.tool.invoke', (params: any) => {
      this.handleToolInvoke(params);
    });

    // Handle thinking content
    jsonRpcHandler.onNotification('chat.thinking', (params: any) => {
      this.handleThinking(params);
    });

    // Handle usage information
    jsonRpcHandler.onNotification('chat.usage', (params: any) => {
      this.handleUsage(params);
    });

    // Handle errors
    jsonRpcHandler.onNotification('chat.error', (params: any) => {
      this.handleError(params);
    });
  }

  /**
   * Get current SDK status (available, version, errors)
   *
   * Side Effects:
   * - Updates `chatStore.sdkStatus` via `setSdkStatus()` with the status information
   * - On error: Still updates store with error information before throwing
   * - Logs errors via `logError()` with ERROR_ID `CHAT_GET_STATUS_FAILED`
   *
   * Returns:
   * - SDKStatus object with sdkAvailable, sdkVersion, and errorMessage
   *
   * Throws:
   * - Re-throws the error after logging and updating store state
   *
   * Timeout: 60 seconds
   */
  async getStatus(): Promise<SDKStatus> {
    try {
      const result = await jsonRpcHandler.sendRequest<any>(
        'chat.status',
        {}
      );

      // Convert snake_case from DR CLI server API to camelCase for TypeScript
      const status: SDKStatus = {
        sdkAvailable: result.sdkAvailable ?? result.sdk_available ?? false,
        sdkVersion: result.sdkVersion ?? result.sdk_version ?? null,
        errorMessage: result.errorMessage ?? result.error_message ?? null,
      };

      // Update store
      const store = useChatStore.getState();
      store.setSdkStatus(status);

      return status;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      logError(
        ERROR_IDS.CHAT_GET_STATUS_FAILED,
        'Failed to get status',
        { error: errorMessage }
      );
      const status: SDKStatus = {
        sdkAvailable: false,
        sdkVersion: null,
        errorMessage: errorMessage,
      };
      useChatStore.getState().setSdkStatus(status);
      throw error;
    }
  }

  /**
   * Send a chat message and stream the assistant response
   *
   * Side Effects (in order):
   * 1. Generates new message and conversation IDs if needed
   * 2. Updates `this.currentConversationId` instance variable
   * 3. Calls `chatStore.setActiveConversationId()` to update active conversation
   * 4. Calls `chatStore.addMessage()` to add user message
   * 5. Calls `chatStore.addMessage()` to add empty assistant message with `isStreaming: true`
   * 6. Calls `chatStore.setStreaming(true)` to mark streaming state as active

