/**
   * Connect to the WebSocket server
   */

source:
connect(): void {
  if (this.ws && this.ws.readyState === WS_OPEN) {
    console.log('[WebSocket] Already connected');
    return;
  }

  // If we've determined REST mode, don't try to connect
  if (this.mode === 'rest') {
    console.log('[WebSocket] Using REST mode, skipping WebSocket connection');
    this.emit('rest-mode', {});
    return;
  }

  // Tear down any prior socket that is not OPEN (e.g. still CONNECTING) before
  // creating a new one. React StrictMode double-invokes the bootstrap effect
  // (connect → cleanup → connect); a CONNECTING socket from the first connect
  // would otherwise be orphaned here — `this.ws` gets overwritten below while
  // the old socket keeps its `onmessage` binding, completes its handshake, and
  // stays open. The server then broadcasts chat chunks to BOTH sockets,
  // doubling streamed text. Detach + close the old socket so exactly one
  // connection ever delivers messages.
  if (this.ws) {
    this.ws.onopen = null;
    this.ws.onmessage = null;
    this.ws.onerror = null;
    this.ws.onclose = null;
    this.ws.close();
    this.ws = null;
  }

  this.isIntentionallyClosed = false;

  // Only log connection attempts during detection phase
  if (this.mode === 'detecting') {
    console.log(`[WebSocket] Attempting WebSocket connection (attempt ${this.reconnectAttempts + 1}/${this.maxConnectionAttempts})...`);
  }

  try {
    // Use protocols parameter to pass auth token instead of query params
    // This sends the token via Sec-WebSocket-Protocol header
    const protocols = this.getAuthProtocols();

    this.ws = new WebSocket(this.url, protocols);

    this.ws.onopen = this.handleOpen.bind(this);
    this.ws.onmessage = this.handleMessage.bind(this);
    this.ws.onerror = this.handleError.bind(this);
    this.ws.onclose = this.handleClose.bind(this);

    // Set connection timeout for initial detection
    if (this.mode === 'detecting') {
      this.connectionTimeout = setTimeout(() => {
        if (this.ws && this.ws.readyState !== WS_OPEN) {
          console.log('[WebSocket] Connection timeout during detection phase');
          this.ws.close();
        }
      }, 3000); // 3 second timeout
    }
  } catch (error) {
    if (this.mode === 'detecting') {
      console.debug('[WebSocket] Connection error during detection:', error);
      this.handleConnectionFailure();
      // Capture error for debugging
      this.connectionErrors.push(error instanceof Error ? error : new Error(String(error)));
    } else {
      logError(
        ERROR_IDS.WS_CONNECTION_ERROR,
        'WebSocket connection error',
        { error: error instanceof Error ? error.message : String(error) }
      );
      this.scheduleReconnect();
    }
  }
}

import { useCallback, useEffect, useRef, useState } from 'react';

/**
 * Tracks which item the pointer has rested on for at least `delayMs`.
 * Feed `onHover` from a hover-change callback (an id, or undefined on
 * leave); `dwelledId` becomes that id once it has stayed hovered for the
 * full delay, and clears as soon as the hover moves or ends.
 *
 * Used by Canvas to hold the graph's edge predicate tooltip back for
 * `PREDICATE_TOOLTIP_DELAY_MS`, fed from GraphCanvas's `onEdgeHover`.
 */
export function useHoverDwell(delayMs: number) {
  const [dwelledId, setDwelledId] = useState<string | undefined>();
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const onHover = useCallback(
    (id: string | undefined) => {
      if (timerRef.current) clearTimeout(timerRef.current);
      timerRef.current = null;
      setDwelledId((current) => (current === id ? current : undefined));
      if (id === undefined) return;
      timerRef.current = setTimeout(() => {
        timerRef.current = null;
        setDwelledId(id);
      }, delayMs);
    },
    [delayMs],
  );

  useEffect(
    () => () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    },
    [],
  );

  return { dwelledId, onHover };
}

