  }
  const cardSize = {
    width: tooltipRef.current.offsetWidth,
    height: tooltipRef.current.offsetHeight,
  };
  const next = computeTooltipPosition(anchorRect, cardSize, placement);
  setPosition((prev) => (samePosition(prev, next) ? prev : next));
};

