interface ErrorContext {
  [key: string]: unknown;
}

interface ErrorWithMetadata extends Error {
  errorId?: ErrorId;
  context?: ErrorContext;
  category?: ExceptionCategory;
  severity?: ExceptionSeverity;
  isExpectedFailure?: boolean;
  isTransient?: boolean;
