export function modelElementNeighborhoodGraph(
  elementId: string,
  model: ModelDerived,
  index: ModelIndex,
): NeighborhoodGraph {
  const center = index.byUuid.get(elementId);
  if (!center) {
    return { nodes: [], edges: [], empty: true };
  }

  // Collect all unique neighbors and the predicates connecting to them.
  const neighbors = new Map<string, ModelNode>();
  const edgesByTargetId = new Map<string, NeighborhoodEdge[]>();

  for (const link of model.links) {
    const src = resolveEndpoint(index, link.source);
    const tgt = resolveEndpoint(index, link.target);
    if (!src || !tgt) continue;

    let isOutgoing = false;
    let neighbor: ModelNode | undefined;

    if (src.id === elementId) {
      isOutgoing = true;
      neighbor = tgt;
    } else if (tgt.id === elementId) {
      isOutgoing = false;
      neighbor = src;
    }

    if (!neighbor) continue;

    // Skip self-loops where the neighbor is the center node.
    if (neighbor.id === elementId) continue;

    // Track the neighbor (dedup by UUID).
    neighbors.set(neighbor.id, neighbor);

    // Track the edge.
    if (!edgesByTargetId.has(neighbor.id)) {
      edgesByTargetId.set(neighbor.id, []);
    }
    edgesByTargetId.get(neighbor.id)!.push({
      id: link.id,
      predicate: link.type,
      direction: isOutgoing ? 'out' : 'in',
      targetId: neighbor.id,
    });
  }

  // Build the nodes array: center first, then neighbors.
  const nodes: NeighborhoodNode[] = [
    {
      id: center.id,
      name: center.name,
      kind: center.type,
      layer: center.layer_id,
      isCenter: true,
    },
  ];

  for (const neighbor of neighbors.values()) {
    nodes.push({
      id: neighbor.id,
      name: neighbor.name,
      kind: neighbor.type,
      layer: neighbor.layer_id,
      isCenter: false,
    });
  }

  // Build edges array: one edge per (neighbor, predicate, direction) triple.
  const edges: NeighborhoodEdge[] = [];
  for (const neighborEdges of edgesByTargetId.values()) {
    for (const edge of neighborEdges) {
      edges.push(edge);
    }
  }

  return {
    nodes,
    edges,
    empty: neighbors.size === 0,
  };
}

/**
 * predicateDefinitions — human-readable descriptions for DR relationship
 * predicates, backing the predicate hover tooltip (edge tooltips + the edge
 * inspector).
 *
 * Source of truth is the DR CLI's own relationship catalog
 * (`.dr/relationship-catalog.json` in this repo, generated from
 * `documentation_robotics`'s `spec/schemas/base/relationship-catalog.json`),
 * which carries `description`, `category`, and `archimateAlignment` for each
 * predicate. That catalog covers most — but not all — of the predicate
 * strings actually used across `/api/model` `links[].type` and `/api/spec`
 * `relationshipSchemas[].predicate` in the live fixture model (66 distinct
 * predicates vs. the catalog's 47): entries the catalog doesn't define are
 * hand-authored below from their usage context (which layers' relationship
 * schemas reference them), using the catalog's own category vocabulary
 * (`motivation` / `business` / `security` / `structural` / `dependency` /
 * `behavioral` / `apm` / `testing` / `traceability` / `governance` / `ux` /
