import { useCallback, useEffect, useRef } from 'react';
import type {
  GraphViewport,
  GraphViewportCause,
  GraphViewportHandle,
  GraphViewportSnapshot,
} from '@tinkermonkey/heimdall-ui';
import { useUiStore } from './uiStore';
import { roundViewport, sameViewport } from './graphViewport';

/**
 * Connects the Model/Schema GraphCanvas to `uiStore.graphViewport`, which the
 * router mirrors into `?vp=` (see router.tsx). Spread the result onto
 * GraphCanvas.
 *
 * - Records a viewport when the user stops panning/zooming (`onViewportDwell`)
 *   and when the canvas moves itself (`onViewportNavigate`: centerOnSelect,
 *   toolbar fit, fullscreen fit). The mount fit isn't recorded, so a plain
 *   link stays plain until someone actually moves.
 * - Restores the stored viewport at mount (`initialViewport`, for reloads and
 *   deep links) and when it changes from outside, i.e. back/forward, through a
 *   silent `setViewport` so the restore doesn't record a new entry. The silent
 *   call also cancels the pending centerOnSelect report when the same
 *   back/forward step restores a selection.
 */
export function useViewportHistory(canvasKey: string) {
  const graphViewport = useUiStore((s) => s.graphViewport);
  const setGraphViewport = useUiStore((s) => s.setGraphViewport);
  const viewportRef = useRef<GraphViewportHandle>(null);
  // The viewport the canvas is showing as far as we know: the last one it
  // reported or the last one we applied. A store value equal to this came
  // from the canvas itself and must not be applied back to it.
  const shownRef = useRef<{ key: string; vp: GraphViewport } | null>(null);

  const scoped = graphViewport && graphViewport.scope === canvasKey ? graphViewport : null;

  const record = useCallback(
    (snapshot: GraphViewportSnapshot) => {
      const vp = roundViewport(snapshot);
      shownRef.current = { key: canvasKey, vp };
      setGraphViewport({ scope: canvasKey, ...vp });
    },
    [canvasKey, setGraphViewport],
  );

  const onViewportNavigate = useCallback(
    (snapshot: GraphViewportSnapshot, cause: GraphViewportCause) => {
      if (cause.kind === 'fit' && cause.reason === 'mount') return;
      record(snapshot);
    },
    [record],
  );

  useEffect(() => {
    if (!scoped) return;
    const shown = shownRef.current;
    if (shown && shown.key === canvasKey && sameViewport(shown.vp, scoped)) return;
    const vp: GraphViewport = { center: scoped.center, zoom: scoped.zoom };
    shownRef.current = { key: canvasKey, vp };
    // Before the canvas has framed its first layout this just replaces that
    // framing, same as initialViewport, so the mount case is harmless too.
    viewportRef.current?.setViewport(vp, { silent: true, animate: true });
  }, [scoped, canvasKey]);

  return {
    viewportRef,
    initialViewport: scoped ? { center: scoped.center, zoom: scoped.zoom } : undefined,
    onViewportDwell: record,
    onViewportNavigate,
  };
}

export interface ModelIndex {
  /** endpoint id (UUID or dotted) -> node */
  byEndpoint: Map<string, ModelNode>;
  /** node UUID -> node */
  byUuid: Map<string, ModelNode>;
}

/**
 * changesets — pure, stateless helpers that map the live `/api/changesets/:id`
 * change records into op-coded view-models for the canvas diff list.
 *
 * Live `change` shape (verified against the running CLI):
 *   { type, elementId, layerName, before?, after?, timestamp, sequenceNumber }
 * where:
 *   - `add`               → `after` only (full element object)
 *   - `delete`            → `before` only (full element object)
 *   - `update`            → both `before` + `after` (full element objects)
 *   - `relationship-add`  → `after` only ({ source, target, predicate, ... })
 *   - `relationship-delete` → `before` only ({ source, target, predicate, ... })
 *
 * Op colors (from the design): add = emerald (#10B981), update = cyan (#22D3EE),
 * delete = rose (#F43F5E) — these are the bright dark-canvas text colors. On the
 * LIGHT canvas the same hues over a pale 12% tint fall below WCAG AA, so each op
 * also carries a darker `colorLight` (the -700 shade) used for the light tone.
 * Relationship add/delete reuse the add/delete colors.
 */

import type { DiffLine } from '@tinkermonkey/heimdall-ui';

/** The four op buckets the UI renders (badge color + 3-char label). */
export type ChangeOp = 'add' | 'update' | 'delete';

/**
 * A relationship that still references an element a `delete` change removes
 * (and that the changeset doesn't delete itself): the delete is refused at
 * commit unless the reviewer chose to delete these links with it.
 */
export interface DeleteBlocker {
  /** `source::predicate::target`. */
  relationshipId: string;
  /** `in`: the other element points at the deleted one; `out`: the reverse. */
  direction: 'in' | 'out';
  /** Dotted id of the element at the relationship's other end. */
  otherElementId: string;
  predicate: string;
}

/** A raw change record from `/api/changesets/:id`. */
export interface ChangeRecord {
  type?: string;
  elementId?: string;
  layerName?: string;
  before?: Record<string, unknown> | null;
  after?: Record<string, unknown> | null;
  timestamp?: string;
  sequenceNumber?: number;
  /** `delete` changes only, from a dr CLI with changeset review. */
  blockers?: DeleteBlocker[];
  /**
   * Who decided the change (codebase_extract's Tier 0 / Tier 1 / the agent).
   * Absent on hand-made changes and from an older dr CLI. Read it through
   * `originOf` (data/tier1.ts), which checks the shape.
   */
  origin?: unknown;
  [key: string]: unknown;
}

/** Op metadata: short uppercase label + the badge color (CSS hex). */
export interface OpMeta {
  /** Normalized op bucket. */
  op: ChangeOp;
  /** Short badge label (e.g. 'ADD'). */
  label: string;
  /** Badge text/border color on the dark canvas (bright hex). */
  color: string;
  /** Badge text color on the light canvas (darker -700 shade; AA on the pale tint). */
  colorLight: string;
  /** Badge background (translucent tint of `color`, works in both tones). */
  background: string;
}

const OP_META: Record<ChangeOp, OpMeta> = {
  add: {
    op: 'add', label: 'ADD',
    color: '#10B981', colorLight: '#047857', background: 'rgba(16,185,129,0.12)',
  },
  update: {
    op: 'update', label: 'MOD',
    color: '#22D3EE', colorLight: '#0E7490', background: 'rgba(34,211,238,0.12)',
  },
  delete: {
    op: 'delete', label: 'DEL',
    // rose-400, not rose-500: #F43F5E on the dark tinted row was 3.5:1, below AA
    // for 10px text; #FB7185 is 4.8:1.
    color: '#FB7185', colorLight: '#BE123C', background: 'rgba(244,63,94,0.12)',
  },
};

/**
 * Normalize a raw change `type` to one of the three op buckets.
 * `relationship-add` → add, `relationship-delete` → delete, etc.
 */
export function normalizeOp(type: string | undefined): ChangeOp {
  const t = (type ?? '').toLowerCase();
  if (t.includes('delete') || t === 'del' || t === 'remove') return 'delete';
  if (t.includes('add') || t === 'create') return 'add';
  return 'update';
}

/** Op metadata (label + colors) for a raw change `type`. */
export function opMeta(type: string | undefined): OpMeta {
  return OP_META[normalizeOp(type)];
}

/** A diff-list row view-model: op badge + element path + a one-line detail. */
export interface ChangeRow {
  /** Stable key for React (elementId + sequence). */
  key: string;
  /** Normalized op bucket. */
  op: ChangeOp;
  /** Op badge metadata. */
  meta: OpMeta;
  /** Dotted element id / relationship id (mono path). */
  elementId: string;
  /** Layer slug the change belongs to. */
  layerName: string;
  /** Human-readable detail line derived from before/after. */

export interface PredicateTooltipProps {
  /** The trigger element the tooltip attaches to. */
  children: ReactNode;
  /** DR predicate string for the hovered edge, e.g. `depends-on`. */
  predicate: string;
  /** Human label for the edge's source node type, e.g. `Object Schema`. */
  sourceTypeLabel: string;
  /** Human label for the edge's destination node type. */
  destinationTypeLabel: string;
  placement?: TooltipPlacement;
  className?: string;
  'data-testid'?: string;
}

const refetch = () => {
  queryClient.invalidateQueries({ queryKey: ['getapichangesets'] });
  queryClient.invalidateQueries({ queryKey: ['getapichangesetschangesetId'] });
  // An extraction stages a changeset as it spends: Tier 1's month moves with it.
  queryClient.invalidateQueries({ queryKey: ['getapitier1'] });
};

/**
 * PredicateTooltip — the "edge" rich hover tooltip content variant: the
 * predicate's own definition plus a generic
 * source-type → predicate → destination-type diagram for the specific edge
 * being hovered. Built on `RichTooltip` so it's the same card component
 * regardless of which surface triggers it (graph edge, sidebar row, page
 * view relationship row — wiring is later phases; this component only needs
 * the edge's already-resolved type labels + predicate string).
 *
 * Definition text comes from `data/predicateDefinitions.ts` (DR's predicate
 * catalog); an unrecognized predicate still renders the diagram with a
 * fallback message rather than hiding the tooltip.
 */

import type { ReactNode } from 'react';
import { RichTooltip, type TooltipPlacement } from './RichTooltip';
import { predicateDefinition } from '../data/predicateDefinitions';

/** How long the pointer must rest on a predicate before its explanation
 *  opens. Long on purpose: predicates are also click targets (navigate /
 *  select the edge), and a quick tooltip covered them while users were
 *  aiming. Keyboard focus still opens it immediately (see RichTooltip). Used
 *  for both PredicateTooltip and the graph's edge tooltip (Canvas.tsx). */
export const PREDICATE_TOOLTIP_DELAY_MS = 3000;

export interface PredicateTooltipProps {
  /** The trigger element the tooltip attaches to. */
  children: ReactNode;
  /** DR predicate string for the hovered edge, e.g. `depends-on`. */
  predicate: string;
  /** Human label for the edge's source node type, e.g. `Object Schema`. */
  sourceTypeLabel: string;
  /** Human label for the edge's destination node type. */
  destinationTypeLabel: string;
  placement?: TooltipPlacement;
  className?: string;
  'data-testid'?: string;
}

export interface PredicateTooltipContentProps {
  predicate: string;
  sourceTypeLabel: string;
  destinationTypeLabel: string;
  'data-testid'?: string;
}

/**
 * The tooltip card's body markup, extracted from `PredicateTooltip` so a
 * caller that can't compose `RichTooltip`'s trigger-wrapping (e.g. a graph
 * edge rendered internally by `GraphCanvas`, with no `children` slot to wrap —
 * see `Canvas.tsx`'s `edgeTooltipContent`, shown in a `TooltipCard` anchored
 * to the edge's label) can still reuse the exact same content.
 */
export function PredicateTooltipContent({
  predicate,
  sourceTypeLabel,
  destinationTypeLabel,
  'data-testid': testId = 'predicate-tooltip',
}: PredicateTooltipContentProps) {
  const definition = predicateDefinition(predicate);

  return (
    <div className="rich-tooltip__body" data-testid={`${testId}-content`}>
      <div className="rich-tooltip__title">{predicate}</div>
      <p className="rich-tooltip__description">
        {definition?.description ?? 'No definition available for this predicate.'}
      </p>
      <div className="rich-tooltip__section-label">Relationship</div>
      <div className="rich-tooltip__diagram" data-testid={`${testId}-diagram`}>
        <span className="rich-tooltip__diagram-node">{sourceTypeLabel}</span>
        <span className="rich-tooltip__diagram-arrow" aria-hidden="true">
          →
        </span>
        <span className="rich-tooltip__diagram-predicate">{predicate}</span>
        <span className="rich-tooltip__diagram-arrow" aria-hidden="true">
          →
        </span>
        <span className="rich-tooltip__diagram-node">{destinationTypeLabel}</span>
      </div>
    </div>
  );
}

export function PredicateTooltip({
  children,
  predicate,
  sourceTypeLabel,
  destinationTypeLabel,
  placement,
  className,
  'data-testid': testId = 'predicate-tooltip',
}: PredicateTooltipProps) {
  return (
    <RichTooltip
      content={
        <PredicateTooltipContent
          predicate={predicate}
          sourceTypeLabel={sourceTypeLabel}
          destinationTypeLabel={destinationTypeLabel}
          data-testid={testId}
        />
      }
      placement={placement}
      className={className}
      openDelay={PREDICATE_TOOLTIP_DELAY_MS}
      data-testid={testId}
    >
      {children}
    </RichTooltip>
  );
}

export default PredicateTooltip;

export interface SpecLayerInfo {
  /** Number of node-types declared by the layer schema (`nodeSchemas` keys). */
  typeCount: number;
  /** Ordered node-type ids (short type names, e.g. 'objectschema'). */
  typeIds: string[];
  /** Ordered node-type titles (e.g. 'ObjectSchema'), aligned with typeIds. */
  typeTitles: string[];
  /** Inspiring standard label. */
  standard: string;
}

export function originFilterOptions(
  records: (ChangeRecord | undefined)[],
): { value: OriginFilter; label: string; count: number }[] {
  const counts = new Map<string, number>();
  let none = 0;
  for (const r of records) {
    const by = originOf(r)?.by;
    if (by) counts.set(by, (counts.get(by) ?? 0) + 1);
    else none++;
  }
  if (counts.size === 0) return [];
  const rank = (k: string) => {
    const i = DECIDER_ORDER.indexOf(k);
    return i === -1 ? DECIDER_ORDER.length : i;
  };
  const deciders = [...counts.keys()].sort((a, b) => rank(a) - rank(b) || a.localeCompare(b));
  const cut = (s: string) => (s.length > MAX_FILTER_LABEL ? `${s.slice(0, MAX_FILTER_LABEL - 1)}…` : s);
  const options: { value: OriginFilter; label: string; count: number }[] = [
    { value: ALL_ORIGINS, label: 'All', count: records.length },
    ...deciders.map((by) => ({ value: deciderKey(by), label: cut(deciderLabel(by)), count: counts.get(by)! })),
  ];
  if (none) options.push({ value: NO_ORIGIN, label: 'No origin', count: none });
  return options;
}

/**
 * useModel — thin wrapper over the kept React Query hook `useGetapimodel`.
 *
 * Derives the per-layer element counts and the total relationship count the
 * shell needs (nav tree counts, status bar, footer) from the raw `/api/model`
 * payload (`{ nodes, links }`).
 */

import { useEffect, useMemo } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { useGetapimodel } from '../../../core/services/generatedApiClient';
import { websocketClient } from '../services/websocketClient';

export interface ModelNode {
  id: string;
  spec_node_id?: string;
  type: string;
  layer_id: string;
  name: string;
  description?: string;
  attributes?: Record<string, unknown>;
  [key: string]: unknown;
}

export interface ModelLink {
  id: string;
  source: string;
  target: string;
  type: string;
  layer_id?: string;
  [key: string]: unknown;
}

export interface ModelPayload {
  nodes: ModelNode[];
  links: ModelLink[];
}

export interface ModelDerived {
  nodes: ModelNode[];
  links: ModelLink[];
  /** Element count per layer slug. */
  countsByLayer: Record<string, number>;
  /** Elements grouped by layer slug, in payload order. */
  nodesByLayer: Record<string, ModelNode[]>;
  /** Total relationship (link) count across the model. */
  relCount: number;
}

const EMPTY_DERIVED: ModelDerived = {
  nodes: [],
  links: [],
  countsByLayer: {},
  nodesByLayer: {},
  relCount: 0,
};

export function useModel() {
  const query = useGetapimodel();
  const raw = query.data as ModelPayload | undefined;

  const derived = useMemo<ModelDerived>(() => {
    if (!raw?.nodes) return EMPTY_DERIVED;

    const countsByLayer: Record<string, number> = {};
    const nodesByLayer: Record<string, ModelNode[]> = {};

    for (const node of raw.nodes) {
      const layer = node.layer_id;
      if (!layer) continue;
      countsByLayer[layer] = (countsByLayer[layer] ?? 0) + 1;
      (nodesByLayer[layer] ??= []).push(node);
    }

    return {
      nodes: raw.nodes,
      links: raw.links ?? [],
      countsByLayer,
      nodesByLayer,
      relCount: raw.links?.length ?? 0,
    };
  }, [raw]);

  return { ...query, derived };
}

/**
 * Refetch the model (and changesets) when the `dr visualize` server announces a
 * model change: it broadcasts `{ type: 'model.updated' }` after any write to
 * the model files — a CLI edit, a DrBot change, or a changeset applied from
 * the viewer — and otherwise the 5-minute `staleTime` would keep showing the
 * old model. Mount once (AppShell).
 */
export function useLiveModelUpdates() {
  const queryClient = useQueryClient();
  useEffect(() => {
    const refetch = () => {
      queryClient.invalidateQueries({ queryKey: ['getapimodel'] });
      queryClient.invalidateQueries({ queryKey: ['getapilayerslayerName'] });
      queryClient.invalidateQueries({ queryKey: ['getapichangesets'] });
      queryClient.invalidateQueries({ queryKey: ['getapichangesetschangesetId'] });
    };
    websocketClient.on(MODEL_UPDATED_EVENT, refetch);
    return () => websocketClient.off(MODEL_UPDATED_EVENT, refetch);
  }, [queryClient]);
}

