const runApply = () => {
  setConfirming(null);
  setError(null);
  mutateWithBody(commit.mutate)(local ? undefined : model.apply.body, {
    onSuccess: (data) => {
      const result = data as ChangesetActionResult;
      setSettled('apply');
      onResult(result, `Applied ${plural(result.committed ?? lands, 'change')} to the model`);
    },
    onError: (err) => {
      if (isDriftError(err)) {
        setError(
          "Nothing was written. The model changed after this was staged. Your decisions are kept: ask DrBot to restage, then review only what moved.",
        );
        return;
      }
      const blockers = commitBlockers(err);
      if (blockers) {
        // The server sees links our copy didn't: refetch so they show.
        queryClient.invalidateQueries({ queryKey: ['getapichangesetschangesetId', detail.id] });
        const lines = Object.entries(blockers).map(([seq, list]) => {
          const item = model.bySeq.get(Number(seq));
          const links = list
            .map((b) => (b as { relationshipId?: string }).relationshipId)
            .filter(Boolean)
            .map((id) => id!.split('::').map((part, i) => (i === 1 ? part : (model.nameOf(part) ?? part))).join(' '));
          return `change ${seq} (${item?.name ?? 'delete'}): ${links.join('; ') || 'links still use it'}`;
        });
        setError(
          `Nothing was written. These deletes would leave links pointing at nothing:\n${lines.join('\n')}\nKeep the link deletes, choose Delete the links too, or keep the element.`,
        );
        return;
      }
      setError(changesetActionErrorMessage(err));
    },
  });
};

/**
 * ErrorBoundary — keeps a render error in one part of the view from blanking
 * the whole viewer (React unmounts the entire tree on an uncaught error).
 * Shows a short alert in place of the failed part instead. Used around the
 * parts that render payloads people can hand-edit or an unexpected server can
 * shape: the changeset review panel, the change inspector and the Tier 1
 * panel. Give it a `key` that changes with what it shows (e.g. the changeset
 * id) so a different payload gets a fresh try.
 */

import { Component, type ErrorInfo, type ReactNode } from 'react';

interface Props {
  /** What failed, for the message: "this changeset's review". */
  what: string;
  children: ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: unknown): State {
    return { error: error instanceof Error ? error : new Error(String(error)) };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error(`[viewer] couldn't show ${this.props.what}:`, error, info.componentStack);
  }

  render() {
    if (this.state.error) {
      return (
        <div role="alert" className="drv-alert" data-testid="error-boundary">
          Couldn&apos;t show {this.props.what}: {this.state.error.message}
        </div>
      );
    }
    return this.props.children;
  }
}

export default ErrorBoundary;

